(ns eurozone.test-runner
  (:require [clojure.test :as t] [agricola.engine-test] [agricola.five-player-test] [agricola.draw-test] [agricola.card-game-test] [agricola.card-timing-test] [agricola.expansion-cards-test] [agricola.artifex-interactions-test] [agricola.granted-actions-test] [agricola.artifex-crop-test] [agricola.artifex-nested-actions-test] [agricola.bot-test] [agricola.action-space-test] [agricola.card-study-test] [agricola.card-rank-experiment-test] [agricola.afterstate-value-test] [agricola.growth-learning-test] [agricola.growth-value-test] [agricola.action-rank-test] [agricola.learning-rewards-test] [agricola.policy-guidance-test] [eurozone.server-test] [eurozone.store-test] [eurozone.table-flow-test] [eurozone.chat-test] [eurozone.table-layout-test] [eurozone.peer-test] [eurozone.discord-test] [eurozone.bot-player-test] [eurozone.card-values-test] [eurozone.play-values-test]))
(defn -main [& _]
  (let [{:keys [fail error]} (t/run-tests 'agricola.engine-test 'agricola.five-player-test 'agricola.draw-test 'agricola.card-game-test 'agricola.card-timing-test 'agricola.expansion-cards-test 'agricola.artifex-interactions-test 'agricola.granted-actions-test 'agricola.artifex-crop-test 'agricola.artifex-nested-actions-test 'agricola.bot-test 'agricola.action-space-test 'agricola.card-study-test 'agricola.card-rank-experiment-test 'agricola.afterstate-value-test 'agricola.growth-learning-test 'agricola.growth-value-test 'agricola.action-rank-test 'agricola.learning-rewards-test 'agricola.policy-guidance-test 'eurozone.server-test 'eurozone.store-test 'eurozone.table-flow-test 'eurozone.chat-test 'eurozone.table-layout-test 'eurozone.peer-test 'eurozone.discord-test 'eurozone.bot-player-test 'eurozone.card-values-test 'eurozone.play-values-test)]
    (shutdown-agents)
    (System/exit (if (zero? (+ fail error)) 0 1))))
